#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: formulario de contacto en producción (tarea 16, parte 3). Crea el
# widget de Turnstile y carga dos secretos al Worker `app`.
# Uso (raíz del repo): & "C:\Program Files\Git\bin\bash.exe" scripts/wizard-contacto.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4
WORKER="app"
HOST="app.plektia.workers.dev"
REF="xggajfivycgttmgbvgys"

# Los secretos van directo al Worker: nada se guarda en disco.
ENV_FILE="/dev/null"

# En Git Bash, explorer.exe convierte `=/…` en rutas: se abre el navegador con
# el manejador de URLs de Windows.
if command -v rundll32.exe >/dev/null 2>&1; then
  open_url() {
    printf '  %s↗ abriendo%s %s\n' "$GREEN" "$RESET" "$1"
    MSYS_NO_PATHCONV=1 rundll32.exe url.dll,FileProtocolHandler "$1" >/dev/null 2>&1 ||
      warn "no pude abrir el navegador; abrí la URL a mano: $1"
  }
fi

# Carga un secreto al Worker leyendo el valor por stdin (nunca queda en la
# terminal ni en el historial).
put_worker_secret() {
  if printf '%s' "$2" | pnpm exec wrangler secret put "$1" --name "$WORKER" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$1")
    printf '  %s✓ set%s secreto %s en el Worker %s\n' "$GREEN" "$RESET" "$1" "$WORKER"
  else
    SKIPPED+=("secreto $1: pnpm exec wrangler secret put $1 --name $WORKER")
    warn "no pude guardar el secreto $1"
  fi
}

banner "Plektia · formulario de contacto en producción"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: sesión de wrangler"
say "Los secretos del Worker se cargan con wrangler, con tu sesión de Cloudflare."
WHOAMI=$(pnpm exec wrangler whoami 2>&1 || true)
if printf '%s' "$WHOAMI" | grep -qi "not authenticated\|You are not"; then
  step "Se va a abrir el navegador para autorizar a wrangler: aceptá con tu cuenta."
  pause
  pnpm exec wrangler login
else
  step "Ya tenés sesión de wrangler."
fi
pnpm exec wrangler whoami 2>&1 | grep -iE "logged in|email|account" | head -3 || true
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: widget de Turnstile"
open_url "https://dash.cloudflare.com/?to=/:account/turnstile"
step "Tocá \"Add widget\" (Agregar widget)."
step "Widget name: Plektia contacto"
step "Hostname: agregá ${BOLD}${HOST}${RESET} (solo ese)."
step "Widget mode: Managed. Pre-clearance: No. Creá el widget."
step "Te muestra dos claves: la ${BOLD}Site Key${RESET} (pública) y la ${BOLD}Secret Key${RESET}."
say "Si el panel no acepta el hostname o las opciones se llaman distinto, frená y avisame."
ask SITE_KEY "Pegá la Site Key (pública, empieza con 0x)"
until [[ "$SITE_KEY" =~ ^0x[A-Za-z0-9_-]{10,}$ ]]; do
  warn "No parece una Site Key de Turnstile (empieza con 0x)."
  ask SITE_KEY "Pegá la Site Key"
done
# La Site Key es pública: va en wrangler.jsonc y se versiona.
if sed -i "s#\"TURNSTILE_SITE_KEY\": \"[^\"]*\"#\"TURNSTILE_SITE_KEY\": \"${SITE_KEY}\"#" wrangler.jsonc &&
  grep -q "\"TURNSTILE_SITE_KEY\": \"${SITE_KEY}\"" wrangler.jsonc; then
  printf '  %s✓ escrita%s la Site Key en wrangler.jsonc\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Site Key: poné \"TURNSTILE_SITE_KEY\": \"${SITE_KEY}\" en wrangler.jsonc")
  warn "no pude escribir la Site Key en wrangler.jsonc"
fi
ask_secret TURNSTILE_SECRET "Pegá la Secret Key (no se va a ver)"
until [[ "$TURNSTILE_SECRET" =~ ^0x[A-Za-z0-9_-]{10,}$ ]]; do
  warn "No parece una Secret Key de Turnstile (empieza con 0x)."
  ask_secret TURNSTILE_SECRET "Pegá la Secret Key"
done
put_worker_secret "TURNSTILE_SECRET_KEY" "$TURNSTILE_SECRET"
unset TURNSTILE_SECRET
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Supabase: clave secreta para el Worker"
open_url "https://supabase.com/dashboard/project/${REF}/settings/api-keys"
say "El Worker la usa solo para guardar mensajes de contacto (función ingest_contact_message)."
step "En la sección ${BOLD}Secret keys${RESET}, tocá \"+ New secret key\" (o \"Add new secret key\")."
step "Nombre: plektia-worker. Creala."
step "Copiá la clave nueva (empieza con sb_secret_). Si aparece oculta, tocá el ojo o \"Copy\"."
say "No reuses otra clave: una propia del Worker se puede revocar sin afectar nada más."
ask_secret SB_SECRET "Pegá la clave secreta (no se va a ver)"
until [[ "$SB_SECRET" =~ ^sb_secret_[A-Za-z0-9_-]{10,}$ ]]; do
  warn "No parece una clave secreta de Supabase (empieza con sb_secret_)."
  ask_secret SB_SECRET "Pegá la clave secreta"
done
put_worker_secret "SUPABASE_SECRET_KEY" "$SB_SECRET"
unset SB_SECRET
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Verificación"
say "Ahora se muestra el resumen y, debajo, lo que quedó cargado."
pause
finish
say "Secretos cargados en el Worker ${WORKER} (solo los nombres):"
pnpm exec wrangler secret list --name "$WORKER" 2>/dev/null | grep -oE '"name": *"[A-Z_]+"' || warn "no pude listar los secretos"
say "Cambio en wrangler.jsonc (la Site Key es pública):"
git --no-pager diff --stat -- wrangler.jsonc || true
step "Listo. Avisale a Claude: \"listo\". Él commitea la Site Key y mergea el PR."
